def normalize(text: str) -> str:
    text = re.sub(r"(?m)^\d{3,}\s*$", "", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return re.sub(r"\n[ \t]+", "\n", text)


def extract_base_clauses(source: str) -> dict[str, str]:
    base = source.split("# ระเบียบว่าด้วยการรักษาความลับของทางราชการ (ฉบับที่ 2)")[0]
    pattern = re.compile(r"^#### ข้อ\s*(\d+)\s*\n(.*?)(?=^#### ข้อ\s*\d+|^#{1,3}\s|\Z)", re.M | re.S)
    clauses = {}
    for number, body in pattern.findall(base):
        clauses[number] = normalize(body)
    return clauses


def apply_amendment(clauses: dict[str, str]) -> dict[str, str]:
    clauses["5"] = re.sub(
        r"“หัวหน้าหน่วยงานของรัฐ” หมายความว่า.*?(?=“การปรับชั้นความลับ”)",
        UPDATED_HEAD_OF_AGENCY + "\n\n",
        clauses["5"],
        flags=re.S,
    )
    clauses.update(REPLACEMENTS)
    clauses["29"] = clauses["29"] + "\n\nแบบรายงานการตรวจสอบข้อมูลข่าวสารลับให้เป็นไปตามที่นายกรัฐมนตรีกำหนดโดยประกาศในราชกิจจานุเบกษา"
    clauses["29/1"] = "ให้หน่วยงานของรัฐรายงานผลการปฏิบัติเกี่ยวกับข้อมูลข่าวสารลับตามระเบียบนี้ภายในเดือนมีนาคมของทุกปี ต่อคณะกรรมการข้อมูลข่าวสารของราชการตามแบบที่นายกรัฐมนตรีกำหนดโดยประกาศในราชกิจจานุเบกษา\n\nเมื่อคณะกรรมการข้อมูลข่าวสารของราชการได้รับรายงานผลการปฏิบัติเกี่ยวกับข้อมูลข่าวสารลับตามวรรคหนึ่งแล้ว ให้ตรวจสอบการปฏิบัติตามรายงานดังกล่าว และรายงานผลการตรวจสอบต่อนายกรัฐมนตรีโดยจะมีข้อคิดเห็นและข้อเสนอแนะด้วยก็ได้"
    return clauses


