def main() -> None:
    clauses = apply_amendment(extract_base_clauses(SOURCE.read_text(encoding="utf-8")))
    ordered_numbers = [str(i) for i in range(1, 30)] + ["29/1"] + [str(i) for i in range(30, 54)]
    articles = []
    for number in ordered_numbers:
        if number not in clauses:
            raise ValueError(f"Missing clause {number}")
        key_point, summary = NOTES[number]
        articles.append({"number": number, "section": SECTION_BY_CLAUSE[number], "keyPoint": key_point, "plainSummary": summary, "lawText": clauses[number]})
    ts = """/**\n * Design reminder — ห้องเรียนพาสเทลแบบเล่าเรื่อง:\n * หน้านี้ใช้ข้อความจากระเบียบ พ.ศ. 2544 รวมฉบับแก้ไข พ.ศ. 2561\n * โดยคำอธิบายรายข้อยึดตัวบทและใช้มาตรฐานคำถามเดียวกับหน้าแรก\n */\nimport type { LawArticle, QuizQuestion } from \"@/data/law\";\n\nexport const secrecyArticles: LawArticle[] = """ + json.dumps(articles, ensure_ascii=False, indent=2) + ";\n\nexport const secrecyQuiz: QuizQuestion[] = " + json.dumps(QUIZ, ensure_ascii=False, indent=2) + ";\n"
    OUTPUT.write_text(ts, encoding="utf-8")


if __name__ == "__main__":
    main()
